#include <stdio.h>   /* a preprocessor directive: no semicolon */

// A single-line comment runs to the end of the line.

int main(void)
{
    int width = 4;      /* declaration with an initialiser */
    int height = 3;
    int area;           /* declaration without a value yet */

    area = width * height;       /* assignment statement */
    printf("Area: %d\n", area);  /* function-call statement */

    /* A block groups statements; this one belongs to the if. */
    if (area > 10) {
        printf("That is a big rectangle.\n");
    }
    return 0;
}

