#include <stdio.h>

int main(void)
{
    int a = 17, b = 5;

    printf("%d %d %d %d %d\n", a + b, a - b, a * b, a / b, a % b);
    printf("%d %d %d\n", a > b, a == b, a != b);
    printf("%d %d %d\n", a > 10 && b > 10, a > 10 || b > 10, !(a > 10));

    a += 3;       /* a = a + 3 */
    b *= 2;       /* b = b * 2 */
    printf("%d %d\n", a, b);

    int i = 5;
    int j = i++;  /* j gets 5, then i becomes 6 */
    int k = ++i;  /* i becomes 7, then k gets 7 */
    printf("%d %d %d\n", i, j, k);

    printf("%d\n", 2 + 3 * 4);    /* * binds tighter than +: 14 */
    printf("%d\n", (2 + 3) * 4);  /* parentheses first: 20 */
    return 0;
}

#include <stdio.h>

double circle_area(double radius)
{
    const double pi = 3.14159265358979;
    return pi * radius * radius;
}

void print_line(int width)
{
    for (int i = 0; i < width; i++) {
        printf("-");
    }
    printf("\n");
}

int main(void)
{
    print_line(20);
    printf("radius 1.0: %.2f\n", circle_area(1.0));
    printf("radius 2.5: %.2f\n", circle_area(2.5));
    print_line(20);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int scores[] = {72, 95, 58, 81};
    size_t count = sizeof scores / sizeof scores[0];
    int total = 0;

    for (size_t i = 0; i < count; i++) {
        total += scores[i];
    }
    printf("count = %zu\n", count);
    printf("bytes = %zu\n", sizeof scores);
    printf("average = %.1f\n", (double)total / count);

    scores[2] = 60;             /* write one element */
    int zeros[4] = {0};         /* every element is zero */
    printf("%d %d\n", scores[2], zeros[3]);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int age = 30;
    int *p = &age;                 /* p holds the address of age */

    printf("age = %d\n", age);
    printf("*p  = %d\n", *p);      /* read through the pointer */

    *p = 31;                       /* write through the pointer */
    printf("age = %d\n", age);

    printf("same address: %d\n", p == &age);
    printf("sizeof p = %zu bytes\n", sizeof p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    size_t n = 5;
    int *squares = malloc(n * sizeof *squares);   /* n ints, contents undefined */
    if (squares == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (size_t i = 0; i < n; i++) {
        squares[i] = (int)(i * i);
    }

    double *zeros = calloc(3, sizeof *zeros);     /* 3 doubles, all 0.0 */
    if (zeros == NULL) {
        free(squares);
        return 1;
    }

    for (size_t i = 0; i < n; i++) {
        printf("%d%s", squares[i], i + 1 < n ? " " : "\n");
    }
    printf("%.1f %.1f %.1f\n", zeros[0], zeros[1], zeros[2]);

    free(squares);
    free(zeros);
    squares = NULL;     /* a freed pointer must not be used again */
    return 0;
}

#include <stdio.h>

struct point {
    double x;
    double y;
};

int main(void)
{
    struct point a = {1.5, 2.0};            /* in member order */
    struct point b = {.y = 4.0, .x = 3.0};  /* designated initialisers */
    struct point c = {.x = 9.0};            /* y becomes 0.0 */

    a.x = a.x + 1.0;                        /* member access with . */
    struct point d = a;                     /* copies both members */
    d.y = 100.0;                            /* does not affect a */

    printf("a = (%.1f, %.1f)\n", a.x, a.y);
    printf("b = (%.1f, %.1f)\n", b.x, b.y);
    printf("c = (%.1f, %.1f)\n", c.x, c.y);
    printf("d = (%.1f, %.1f)\n", d.x, d.y);
    printf("sizeof(struct point) = %zu\n", sizeof(struct point));
    return 0;
}

#include <stdio.h>

int main(void)
{
    FILE *out = fopen("scores.txt", "w");
    if (out == NULL) {
        perror("scores.txt");
        return 1;
    }

    const char *names[] = {"ada", "grace", "linus"};
    int scores[] = {91, 78, 85};

    for (int i = 0; i < 3; i++) {
        fprintf(out, "%s %d\n", names[i], scores[i]);
    }
    fclose(out);
    printf("wrote 3 lines\n");
    return 0;
}

