#include <stdio.h>
#include <limits.h>

int will_overflow(int x)
{
    return x + 1 < x;        /* UB when x == INT_MAX; may be folded to 0 */
}

int main(void)
{
    printf("%d\n", will_overflow(INT_MAX));
    return 0;
}
